use std::time::Instant;
use kk_engine::Engine;
use kk_schema::room::{RoomObject, EnergyObj};
fn object() -> RoomObject { RoomObject::Energy(EnergyObj{id:0,x:10,y:10,resource_type:0,amount:1,resource:None}) }
fn main() {
 for n in [500,1000,2000] {
  let mut individual=Engine::default();individual.register_room("W1N1",kk_core::Terrain::plains()).unwrap();
  let start=Instant::now();for _ in 0..n {individual.insert_object("W1N1",object()).unwrap();}let single_ms=start.elapsed().as_secs_f64()*1000.;
  let mut bulk=Engine::default();bulk.register_room("W1N1",kk_core::Terrain::plains()).unwrap();
  let start=Instant::now();bulk.edit_world(|world| {for _ in 0..n {world.insert("W1N1",object())?;} Ok(())}).unwrap();let bulk_ms=start.elapsed().as_secs_f64()*1000.;
  assert_eq!(individual.world().room("W1N1").unwrap().objects.len(),n);
  assert_eq!(bulk.world().room("W1N1").unwrap().objects.len(),n);
  println!("{{\"objects\":{n},\"individual_ms\":{single_ms},\"bulk_ms\":{bulk_ms}}}");
 }
}
